static RList *entries(RBinFile *bf) {
        RList *ret = r_list_newf (free);
        if (ret) {
                struct r_bin_bflt_obj *obj = (struct r_bin_bflt_obj *) R_UNWRAP3 (bf, bo, bin_obj);
                RBinAddr *ptr = r_bflt_get_entry (obj);
                if (ptr) {
